### Affinity Calculation
```go
// internal/worker/affinity.go
func CalculateAffinity(w *Worker, taskKeywords []string) float64 {
    if len(w.TaskHistory) == 0 {
        return 0.5  // Neutral for new workers
    }

    var score float64
    for _, entry := range w.TaskHistory {
        if hasOverlap(entry.Keywords, taskKeywords) {
            switch entry.Outcome {
            case OutcomeSuccess:
                score += 1.0
            case OutcomeHandoff:
                score += 0.3
            case OutcomeFailed:
                score -= 0.5
            }
        }
    }

    // Apply decay (recent history weighted more)
    // Normalize to 0-1 range
    return normalizeScore(score, len(w.TaskHistory))
}
```

### Supervisor Assignment Logic
In `assignIdleWorkerToTask()`:
```go
// Get all idle workers
idleWorkers := reg.List(worker.StatusIdle)

// Extract task keywords from description/title
keywords := extractKeywords(task.Title, task.Description)

// Score workers by affinity
var scored []worker.AffinityScore
for _, w := range idleWorkers {
    score := worker.CalculateAffinity(w, keywords)
    scored = append(scored, worker.AffinityScore{
        WorkerID: w.ID,
        Score:    score,
    })
}

// Sort by score descending, assign highest
sort.Slice(scored, func(i, j int) bool {
    return scored[i].Score > scored[j].Score
})
```

