### Estimation Logic
```go
// internal/complexity/complexity.go
func Estimate(title, description string, fileHints []string) ComplexityEstimate {
    score := 0
    factors := []string{}

    // Length of description
    if len(description) > 1000 {
        score += 2
        factors = append(factors, "detailed description")
    }

    // Keywords indicating complexity
    complexKeywords := []string{"refactor", "migrate", "redesign", "architecture"}
    for _, kw := range complexKeywords {
        if strings.Contains(strings.ToLower(description), kw) {
            score += 2
            factors = append(factors, fmt.Sprintf("contains '%s'", kw))
        }
    }

    // File count hints
    if len(fileHints) > 5 {
        score += 2
        factors = append(factors, fmt.Sprintf("%d files affected", len(fileHints)))
    }

    // Map score to complexity
    switch {
    case score <= 1:
        return ComplexityEstimate{Size: ComplexitySmall, Factors: factors}
    case score <= 3:
        return ComplexityEstimate{Size: ComplexityMedium, Factors: factors}
    case score <= 5:
        return ComplexityEstimate{Size: ComplexityLarge, Factors: factors}
    default:
        return ComplexityEstimate{Size: ComplexityXL, Factors: factors}
    }
}
```

