### Resource Monitoring
```go
// internal/health/monitor.go
import "github.com/shirou/gopsutil/v3/cpu"
import "github.com/shirou/gopsutil/v3/mem"

func GetResourceMetrics() (*HealthMetrics, error) {
    // CPU usage (average over 1 second)
    cpuPercent, err := cpu.Percent(time.Second, false)
    if err != nil {
        return nil, err
    }

    // Memory usage
    memInfo, err := mem.VirtualMemory()
    if err != nil {
        return nil, err
    }

    return &HealthMetrics{
        CPUPercent:    cpuPercent[0],
        MemoryPercent: memInfo.UsedPercent,
    }, nil
}
```

### Failure Rate Tracking
```go
// internal/health/throttle.go
type FailureTracker struct {
    mu       sync.Mutex
    outcomes []taskOutcome  // Ring buffer of last N outcomes
    pos      int
    size     int
}

func (t *FailureTracker) Record(success bool) {
    t.mu.Lock()
    defer t.mu.Unlock()
    t.outcomes[t.pos] = taskOutcome{success: success, time: time.Now()}
    t.pos = (t.pos + 1) % t.size
}

func (t *FailureTracker) FailureRate() float64 {
    t.mu.Lock()
    defer t.mu.Unlock()
    var failures, total int
    for _, o := range t.outcomes {
        if !o.time.IsZero() {
            total++
            if !o.success {
                failures++
            }
        }
    }
    if total == 0 {
        return 0
    }
    return float64(failures) / float64(total)
}
```

### Supervisor Integration
```go
// cmd/foundry/supervisor.go
func runCycle(cfg supervisorConfig, state *supervisorState) {
    // Check health before assignment
    health, err := health.Check(cfg.thresholds, state.failureTracker)
    if err != nil {
        fmt.Printf("⚠️  Health check error: %v\n", err)
    }

    switch health.Status {
    case health.HealthCritical:
        fmt.Printf("🛑 Critical: %s - pausing all assignments\n", health.ThrottleReason)
        return  // Skip assignment entirely
    case health.HealthDegraded:
        fmt.Printf("⚠️  Degraded: %s - reducing worker count\n", health.ThrottleReason)
        cfg.maxConcurrentWorkers = max(1, cfg.maxConcurrentWorkers/2)
    }

    // ... rest of cycle ...
}
```

